import SwiftUI

/**
 *
 * Nexi Payments
 *
 * Allows management of log files
 * generated by the app.
 *
 */
struct LogView: View {
    
    // stores the list of log file URLs.
    @State private var logFiles: [URL] = []
    
    // Optional state; it will keep track of the file the user has selected for sharing.
    // When it is not `nil`, the share sheet will be displayed.
    @State private var selectedFileForSharing: URL?
    
    var body: some View {
        
        VStack(spacing: 20) {
            
            Text("Logs ")
                .bold()
            
            if logFiles.isEmpty {
                
                VStack {
                    
                    Image(systemName: "doc.text.magnifyingglass")
                        .font(.largeTitle)
                        .foregroundColor(.gray)
                    
                    Text("No log file found.")
                        .padding(.top)
                    
                } // VStack
                
            } else {
                
                // Create a list to display log files
                List(logFiles, id: \.self) { fileURL in
                    
                    Button(action: {
                        // When the user taps a row, the selected file is set
                        self.selectedFileForSharing = fileURL
                    }) {
                        
                        HStack {
                            
                            Image(systemName: "doc.text.fill")
                            // Show only the file name, not the full path
                            Text(fileURL.lastPathComponent)
                            
                            Spacer()
                            
                            Image(systemName: "chevron.right")
                                .foregroundColor(.gray.opacity(0.5))
                            
                        } // HStack
                        .foregroundColor(.primary)
                        
                    } // Button
                    
                } // List(logFiles, id:
                
            } // if logFiles.isEmpty {
            
            Spacer()
            
        } // VStack
        .applyDemoBackground()
        .onAppear(perform: loadLogFiles) // Carica i file quando la vista appare
        .sheet(item: $selectedFileForSharing) { fileURL in
                    
            // This sheet is presented when `selectedFileForSharing` is not nil.
            // The `fileURL` is the one that has been selected.
            SharingLogView(fileURL: fileURL)
            
        } // sheet
        
    } // body
    
    // Load log file URLs from the LogManager.
    private func loadLogFiles() {
        
        self.logFiles = LogManager.shared.getLogFileURLs()
        
    }
    
    
} // body

#Preview {
    LogView()
}
